  updated_at      = NOW()
WHERE river_id = '902b13d9-2f6e-49ea-9bbc-f4c8d9e3e99b';

-- Verify update
DO $$
DECLARE
  v_count  int;
  v_lat float8;
  v_lon float8;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM public.river_geometries
  WHERE river_id = '902b13d9-2f6e-49ea-9bbc-f4c8d9e3e99b'
    AND geom IS NOT NULL;

  IF v_count = 0 THEN
    RAISE EXCEPTION 'SF Snake geometry update failed — row not found or geom is null';
  END IF;

  SELECT ST_Y(ST_Centroid(geom)), ST_X(ST_Centroid(geom)) INTO v_lat, v_lon
  FROM public.river_geometries
  WHERE river_id = '902b13d9-2f6e-49ea-9bbc-f4c8d9e3e99b';

  -- Centroid should be in Swan Valley (lat 43.3-43.8, lon -111.9 to -111.1)
  IF v_lat < 43.2 OR v_lat > 44.0 OR v_lon < -112.0 OR v_lon > -111.0 THEN
    RAISE EXCEPTION 'SF Snake centroid (%, %) is outside expected Swan Valley range', v_lat, v_lon;
  END IF;

  RAISE NOTICE 'SF Snake geometry OK — centroid at (%, %)', round(v_lat::numeric, 4), round(v_lon::numeric, 4);
END $$;
